recipe('fish-otah','Coconut fish custard parcels',S,4,200,25,15,[[300,'hoki fillets','F001277','Skin and bones removed'],(100,'onion','Chopped'),(12,'garlic'),(15,'ginger'),(1,'chilli'),[2,'ground turmeric','F009335'],[2,'ground coriander','F003190'],[5,'fish sauce','F008004'],[5,'white sugar','F008976'],(50,'egg'),[100,'coconut milk','F002991']],[ 'Blend onion, garlic, ginger, spices and coconut milk until smooth. Add diced fish, egg, fish sauce and sugar; process into a thick paste.','Divide among eight food-safe banana-leaf parcels, keeping the filling no thicker than 2 cm. Fold securely and fasten with toothpicks; keep leaf ends away from the heating element.','Arrange in one layer and air fry at 200°C for about 15 minutes until firm and 75°C in the middle. Open cautiously and discard leaves and toothpicks before eating.'],'Soft fish and coconut custard sets inside individual leaf parcels with ginger and coriander.',internal=75,allergens=['fish','egg'],equipment=['Food processor','Food-safe banana leaves','Wooden toothpicks'],nutritionNote='Simplified otah-style aromatics omit lemongrass, galangal, shrimp paste and optional sambal. Non-edible banana leaves are packaging, excluded from nutrition. Four servings of two parcels.')
recipe('bell-pepper-stuffed-chicken-roll-ups','Chicken and capsicum roulades',C,2,200,20,16,[(300,'chicken','Two breasts, sliced horizontally into four thin pieces'),(10,'oil'),(20,'lemon'),(3,'paprika'),(2,'cumin'),(1,'oregano'),(150,'capsicum','Fine strips'),(50,'onion','Fine strips')],['Flatten chicken pieces between baking paper to 5 mm thickness. Rub with oil, lemon, paprika, cumin and oregano.','Divide capsicum and onion among the chicken pieces. Roll firmly and secure each with a toothpick, making four short rolls.','Air fry at 200°C for 12–16 minutes, turning after 6 minutes, until the middle of each roll reaches 74°C. Remove all toothpicks before serving.'],'Thin chicken cutlets wrap around sweet capsicum and onion for four quick vegetable-filled rolls.',preheat=3,internal=74,allergens=[],equipment=['Wooden toothpicks'],nutritionNote='Measured chicken weight and individual spices replace source taco seasoning; two substantial portions replace four small source portions.')
recipe('salmon-quiche','Salmon and spring onion quiches',S,4,180,30,40,[[275,'salmon fillet','F007827','Skin removed; cut into 1 cm cubes'],(15,'lemon'),[35,'egg yolk','F003737'],(100,'butter','Cold and diced'),(165,'flour'),(200,'egg','Beaten'),[90,'thickened cream','F003270'],[35,'spring onion','F006250','Finely sliced']],[ 'Rub butter into flour until sandy, then add yolk and 30 g cold water to form dough. Roll into two circles and line two shallow 17 cm quiche tins; chill for 20 minutes.','Whisk whole eggs, cream and lemon. Divide salmon and spring onion between pastry cases, then pour in the egg mixture without overfilling.','Air fry each quiche at 180°C for about 20 minutes, until pastry underneath is cooked and the centre is set and reaches 75°C. Cook sequentially if only one tin fits. Rest 5 minutes and cut each into two.'],'A buttery pastry case holds salmon pieces and spring onion in a softly set egg and cream filling.',preheat=5,wait=25,internal=75,allergens=['fish','egg','milk','wheat','gluten'],equipment=['Two shallow 17 cm air-fryer-safe quiche tins'],nutritionNote='Includes all pastry, egg yolk and filling; 40 minutes accounts for two sequential 20-minute batches. Water is non-nutritive; four half-quiche portions.')
recipe('savory-crab-cakes-1','Crab and capsicum cakes',S,4,180,20,20,[[450,'cooked crab meat','F003243','Picked carefully for shell','cooked'],(50,'egg'),(60,'capsicum','Very finely diced'),[20,'spring onion','F006250','Finely sliced'],(30,'flour'),(30,'crumbs'),(50,'mayo'),[10,'Worcestershire sauce','F008094'],(2,'paprika'),(1,'thyme'),(5,'oil')],['Fold crab, egg, capsicum, spring onion, flour, crumbs, mayonnaise, Worcestershire and spices together without breaking up all the crab flakes.','Form eight patties about 1.5 cm thick. Chill for 20 minutes so they hold their shape, then brush lightly with oil.','Air fry at 180°C in two uncrowded batches for 10 minutes each, turning carefully halfway. Check each cake is firm and reaches 75°C through the centre.'],'Crab flakes, fine capsicum and a little mayonnaise form tender cakes with lightly browned edges.',wait=20,internal=75,allergens=['crustacean','fish','egg','wheat','gluten'],nutritionNote='Cooked crab reference and measured seasonings used; four servings of two cakes. All binding mixture and coating oil counted.')
recipe('herb-lemon-mussels','Garlic and lemon half-shell mussels',S,2,180,10,20,[[250,'steamed mussel meat','F005968','In about 12–16 half shells; weigh edible meat only','cooked'],(15,'oil'),(25,'lemon'),(5,'garlic','Grated'),(5,'parsley','Chopped'),(1,'thyme')],['Use chilled cooked mussels in clean half shells. Mix oil, lemon, garlic, parsley and thyme, then spoon evenly over the mussel meat.','Set shells level in the basket, using an approved rack if needed to prevent spilling. Keep space between them and cook in two batches if required.','Air fry at 180°C for 8–10 minutes per batch until steaming hot and 75°C in the meat. Serve promptly and discard shells.'],'Mussels warm in their half shells under a garlic, lemon and herb dressing.',internal=75,allergens=['mollusc'],nutritionNote='Nutrition uses 250 g edible cooked mussel meat, excluding shell weight. Recipe begins with safely cooked chilled mussels; two sequential batches included in timing.')
recipe('scallops-with-greens','Scallop and spinach cream bake',S,2,200,15,13,[[240,'raw scallops','F008166','Eight large scallops'],[200,'baby spinach','F008749','Wilt, squeeze dry and chop'],[90,'thickened cream','F003270'],(15,'paste'),[5,'fresh basil','F000396','Chopped'],(5,'garlic','Grated'),(5,'oil')],['Wilt spinach briefly in a covered saucepan with a splash of water, cool enough to handle and squeeze out excess moisture. Combine with cream, tomato paste, basil and garlic.','Brush scallops with oil. Arrange in two shallow heat-safe ramekins and spoon spinach mixture around them, leaving their tops exposed.','Air fry at 200°C for 10–13 minutes until scallops are opaque and reach 63°C and the sauce is bubbling. Stand for 2 minutes before eating.'],'Large scallops roast above a creamy spinach and tomato base in individual dishes.',wait=2,internal=63,allergens=['mollusc','milk'],equipment=['Two shallow air-fryer-safe ramekins','Small saucepan'],nutritionNote='Edible scallop weight and fresh spinach are explicit. Two meal portions replace the source eight individual-scallop servings.')
recipe('shrimp-pirogues','Prawn and dill cucumber boats',S,2,200,20,6,[(200,'prawn'),(80,'creamcheese'),(40,'yoghurt'),(10,'lemon'),[5,'fresh dill','F003509','Chopped'],(350,'cucumber','Two short cucumbers'),(3,'oil')],['Brush prawns with oil and air fry at 200°C for 4–6 minutes until opaque and 63°C. Transfer to a clean shallow bowl and refrigerate promptly until cool.','Halve cucumbers lengthways and scoop out the watery seeds. Pat the hollows dry. Chop cooled prawns into small pieces.','Beat cream cheese with yoghurt, lemon and dill, then fold in prawns. Fill the cucumber halves and serve immediately, keeping any unused filling refrigerated.'],'Cool cucumber boats carry a creamy dill filling made with freshly air-fried prawns.',wait=20,internal=63,allergens=['crustacean','milk'],nutritionNote='Prawn amount increased from apparent source typo of 34 g to a defined 200 g; nutrition fully recalculated. Cooling time included. Four boats provide two snack portions.')
recipe('bacon-potato-patties','Bacon and cheddar potato cakes',Q,4,150,20,45,[(600,'potato','Dice, boil and drain before mashing'),(50,'egg'),(90,'crumbs'),(60,'bacon','Finely chopped'),(120,'cheddar','Grated'),(15,'flour')],['Boil potatoes for 15 minutes until tender and drain very well. Air fry bacon at 180°C for 5 minutes while potatoes cook, then finely chop it. Mash potatoes and allow steam to escape.','Fold bacon, cheddar, egg, crumbs and flour into potato. Form eight flat cakes, each about 1.5 cm thick; refrigerate for 10 minutes.','Lower the air fryer to 150°C. Cook cakes in two batches for 15 minutes each, turning halfway, until lightly browned and 75°C inside.'],'Mashed potato, crisp bacon and cheddar turn into substantial patties with a soft centre.',wait=10,internal=75,allergens=['egg','milk','wheat','gluten'],equipment=['Saucepan'],nutritionNote='Uses raw peeled potato input with no butter or milk; all nutrients counted before boiling. Cheddar reduced from source 235 g. Cook time covers potato boiling and two batches, with bacon cooking concurrently.')
recipe('chicken-stuffed-mini-peppers','Creamy chicken stuffed mini capsicums',C,4,190,15,15,[[180,'cooked skinless chicken breast','F002590','Shredded','cooked'],(300,'capsicum','Mini capsicums, halved and deseeded'),(100,'creamcheese'),[25,'parmesan','F002479','Grated'],[5,'fresh basil','F000396','Chopped'],[20,'spring onion','F006250','Sliced'],(5,'garlic','Grated'),(5,'parsley','Chopped'),(1,'paprika')],['Combine chicken, cream cheese, parmesan, herbs, garlic, spring onion and paprika.','Spoon into capsicum halves and arrange level in a shallow approved dish, keeping the filling no deeper than 3 cm.','Use the air fryer bake setting at 190°C for about 15 minutes, until capsicums soften and the centre of the filling reaches 75°C.'],'Mini capsicum halves hold a creamy shredded chicken filling with parmesan and fresh herbs.',internal=75,allergens=['milk'],equipment=['Shallow air-fryer-safe baking dish'],nutritionNote='Uses a cooked chicken reference and defines all ingredient weights. Four snack portions; air-fryer bake mode follows source.')
recipe('pork-belly-bites-with-mushrooms','Pork belly and mushroom bites',M,4,200,15,18,[[450,'rindless pork belly','F006862','Cut into 2 cm cubes'],(230,'mushroom','Halved'),(10,'soy'),(5,'garlic','Grated'),(10,'oil')],['Pat pork belly dry and toss with mushrooms, soy, garlic and oil. Keep the pork cubes similar in size so they cook evenly.','Arrange in a roomy layer and air fry at 200°C for 15–18 minutes, stirring every 5 minutes so mushrooms and pork brown evenly.','Check the thickest pork cube reaches 71°C. Lift out with a slotted spoon and allow 3 minutes before serving.'],'Small rindless pork belly cubes brown alongside mushrooms in a garlic and soy coating.',wait=3,allergens=['soy','wheat','gluten'],nutritionNote='Rindless raw pork belly reference used; rendered fat remaining in basket is not deducted from nutrition.')
recipe('bacon-wrapped-filet-mignon','Bacon-wrapped beef fillet medallions',M,2,200,10,15,[[300,'lean beef fillet','F000836','Two 150 g medallions, about 3 cm thick'],(50,'bacon','Two long thin rashers'),(5,'oil')],['Wrap each medallion around its edge with one bacon rasher and secure with a toothpick. Brush the exposed beef lightly with oil.','Air fry at 200°C for 12–15 minutes, turning halfway, until the beef centre and the bacon reach 71°C. Add short intervals if needed for thicker medallions.','Rest for 5 minutes on a warm plate. Remove both toothpicks and serve with the resting juices.'],'A thin bacon band keeps its shape around a tender beef fillet medallion as both brown in the basket.',preheat=5,wait=5,allergens=[],equipment=['Wooden toothpicks'],nutritionNote='Raw lean beef fillet and raw bacon weighed separately; two defined portions. Cooking to 71°C is a conservative safety endpoint, not a rare steak instruction.')
recipe('bacon-cheese-and-avocado-melt','Bacon and cheese avocado bowls',Q,2,200,15,10,[(200,'avocado','Two intact halves; reserve skins as serving shells'),(60,'bacon','Finely diced'),[30,'tomato salsa','F008056'],[15,'thickened cream','F003270'],(30,'cheddar','Grated')],['Air fry bacon at 180°C for 5 minutes until cooked. Combine with salsa and cream.','Support avocado halves level in shallow ramekins. Spoon bacon mixture into the hollows and scatter cheddar over the filling.','Air fry at 200°C for 3–5 minutes until cheese bubbles and filling reaches 75°C. Eat the flesh and filling; discard the skins.'],'Warm avocado halves hold a small bacon, salsa and melted cheddar filling.',internal=75,allergens=['milk'],equipment=['Two shallow air-fryer-safe ramekins'],nutritionNote='Only the stuffed avocado component is included; the separate source scrambled egg recipe is omitted. Avocado weight is edible flesh, excluding stone and skin.')
